INSERT INTO `indikators` VALUES (86,'I-01',1,31,153,'Total Fertility Rate (TFR)','anak/wanita','Maintain / Stable','PK24 Kemendukbangga/\nBKKBN',1.84,'Indikator Program RPJMD (Program Pengendalian Penduduk)','Ketersediaan alokon untuk akseptor masih perlu dimaksimalkan, Masalah biaya hidup yang tinggi, tingginya partisipasi peremuan di dunia kerja, perubahan gaya hidup generasi muda serta disparitas demografi wilayah',NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(87,'I-02',2,31,153,'Age-Specific Fertility Rate (ASFR) 15-19 tahun','per 1.000 wanita 15-19 th','Lower Better','PK24 Kemendukbangga',39.30,'Indikator Program RPJMD (Program Pengendalian Penduduk)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(88,'I-03',3,31,153,'Proporsi Kebutuhan KB yang Terpenuhi (Demand Satisfied)','%','Higher Better','PK24 Kemendukbangga/\nBKKBN',7.10,'Indikator Kinerja Kunci (IKK) RPJMD Pengendalian Penduduk dan KB',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(89,'I-04',4,32,154,'Rata-Rata Lama Sekolah Penduduk Usia 15 Tahun ke Atas (tahun)','tahun','Higher Better','Susenas BPS',10.91,'Indikator Utama Pembangunan (IUP) RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','1. Anak usia 15 tahun yang ATS (Anak Tidak Sekolah) dikarenakan sudah bekerja dan tidak ingin melanjutkan sekolah                     2. Melanjutkan ke sekolah pondok sehingga tidak tercatat di dapodik Kemendikdasmen                              3. Anak - anak berkebutuhan khusus yang tidak melanjutkan sekolah sehingga tidak tercatat di dapodik Kemendikdasmen','Menggalakkan kembali PKBM (Pusat Kegiatan Belajar Masyarakat) dengan kegiatannya kejar Paket A, B dan C','2026-07-30 08:21:04','2026-09-09 08:28:18'),(90,'I-05',5,32,154,'Angka Partisipasi Kasar (APK) Perguruan Tinggi (%)','%','Higher Better','BPS Kota Sidoarjo \n*APK 19-24 th',18.34,'Indikator Kinerja Daerah (IKD) RPJMD Aspek Daya Saing Daerah (Indikator Proporsi Penduduk Berusia 15 Tahun ke Atas yang Berkualifikasi Pendidikan Tinggi)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(91,'I-06',6,32,156,'Jumlah Tenaga Kerja Tersertifikasi Kompetensi Kerja/ Persentase Pekerja Lulusan Pendidikan Menengah dan Tinggi yang Bekerja di Bidang Keahlian Menengah Tinggi','orang','Higher Better','Dinkopum',NULL,'Indikator Kinerja Kunci (IKK) RPJMD Ketenagakerjaan (Indikator % Pelatihan Berbasis Kompetensi)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(92,'I-07',7,32,154,'Prevalensi Stunting (Persentase Balita dengan Tinggi Badan di Bawah Standar)','%','Lower Better','SKI/SSGI Kemenkes',10.60,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','Data stunting yang diakui adalah data penghitungan dari pusat, yaitu SKI (5 tahun sekali) dan SSGI (1 tahun sekali). Untuk tahun 2025 tidak ada pengukuran SSGI, sehingga angka capaian yang dipakai adalah SSGI pengukuran tahun 2024 yaitu 10,6%.\n10,6 ini tidak diukur berdasarkan TB/ U (umumnya penghitungan stunting), namun menggunakan sistem SAE (Small Area Estimation), yaitu metode untuk memperoleh nilai estimasi parameter yang reliabel pada level sub populasi (area atau domain) dimana ukuran sampelnya tidak cukup atau bahkan tidak ada sampelnya sama sekali. Sehingga angka 10,6 tersebut termasuk dalam salah satu yang RSE (Relative Standar Eror) nya tinggi (> 25%).',NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(93,'I-08',8,32,154,'Angka Kematian Bayi (AKB)','per 1.000 kelahiran hidup','Lower Better','Dinas Kesehatan',NULL,'Indikator Kegiatan Renstra Dinas Kesehatan','Jumlah kematian bayi 2025 adalah 193 orang. Jika disandingkan dengan target nasional (12,62 per 1.000 KH), maka capaian AKB tahun 2025 Kabupaten Sidoarjo masih dibawah target nasional. (Sumber data: MPDN, 2025. Diakses tgl: 14 Januari 2026)\nc) Indikator ini sebenarnya sudah tidak lagi dipasang di renstra baru, tahun 2025-2029. Karena renstra baru menyebutkan Angka Kematian Balita (berdasarkan indikator mandatory RIBK)',NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(94,'I-09',9,32,154,'Angka Kematian Ibu (AKI)','per 100.000 kelahiran hidup','Lower Better','Dinas Kesehatan',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','Jumlah kematian ibu tahun 2025 sebanyak 24 ibu, dan jumlah lahir hidup proyeksi menurut KMK tahun 2025 adalah 29.176',NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(95,'I-10',10,32,158,'Tingkat Kemiskinan','%','Lower Better','Susenas BPS',4.53,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(96,'I-11',11,32,153,'Tingkat Partisipasi Angkatan Kerja Perempuan','%','Higher Better','Sakernas BPS',54.23,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(97,'I-12',12,32,158,'Persentase Pekerja Informal','%','Lower Better','Sakernas BPS',NULL,'Indikator Kegiatan Renstra Dinkopum',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(98,'I-13',13,32,158,'Persentase Penyandang Disabilitas Bekerja di Sektor Formal','orang','Higher Better','Dinas Sosial',NULL,'Indikator Kegiatan Renstra Dinkopum',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(99,'I-14',14,32,158,'Gini Ratio','indeks','Lower Better','Susenas BPS',0.33,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(100,'I-15',15,32,158,'Produk Domestik Regional Bruto (PDRB) Perkapita','juta rupiah','Higher Better','BPS',137.00,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(101,'I-16',16,32,158,'Tingkat Pengangguran Terbuka','%','Lower Better','Sakernas BPS',6.49,'IUP RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(102,'I-17',17,32,122,'Persentase Penambahan Wajib Pajak Hasil Ekstensifikasi','','Higher Better','BPPKAD',NULL,'ndikator Program RPJMD (Program Pengelolaan Pendapatan Daerah, indikator % Objek, subjek pajak baru yang terdata menjadi OP/WP); IUP RPJPD (Indikator Rasio pajak terhadap PDRB)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(103,'I-18',18,33,153,'Indeks Pembangunan Keluarga (i-bangga)','indeks','Higher Better','Kemendukbangga/BKKBN',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(104,'I-19',19,33,153,'Indeks Perlindungan Anak','indeks','Higher Better','SIGA KemenPPPA',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(105,'I-20',20,33,165,'Rumah Tangga dengan Akses Hunian Layak, Terjangkau, dan Berkelanjutan (%)','%','Higher Better','DP2CKTR',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(106,'I-21',21,33,165,'Rumah Tangga dengan Akses Sanitasi Aman (%)','%','Higher Better','DPUPR',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Geografi dan Demografi',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(107,'I-22',22,33,96,'Indeks Lansia Berdaya','','Higher Better','PK23 Kemendukbangga/ BKKBN',NULL,'Indikator Program RPJMD (Program Pemberdayaan dan Peningkatan Keluarga Sejahtera)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(108,'I-23',23,33,153,'Indeks Pengasuhan Keluarga yang Memiliki Remaja','indeks','Higher Better','PK23 Kemendukbangga/ BKKBN',NULL,'Indikator Program RPJMD (Program Pemberdayaan dan Peningkatan Keluarga Sejahtera)',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(109,'I-24',24,33,154,'Cakupan Kepesertaan Jaminan Kesehatan Nasional (%)','%','Higher Better','BPJS Kesehatan',NULL,'Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-09 08:28:18'),(110,'I-25',25,34,96,'Persentase Kampung Kelu